package com.ashura.tutor.domain

import com.ashura.tutor.domain.math.DigitNormalizer
import com.ashura.tutor.domain.math.EvalResult
import com.ashura.tutor.domain.math.ExpressionEvaluator
import com.ashura.tutor.domain.math.UnitConverter

/**
 * Deterministic calculator + unit-conversion tool (spec §11.1).
 * Exact arithmetic is computed, never generated by the language model. Supports full
 * expressions (precedence, parentheses, unary minus, `^`, `%`, sqrt, abs) and
 * conversions such as "convert 5 km to m". Errors are reported explicitly.
 */
class CalculatorTool : TaskController.Tool {

    override val name = "calculator"

    override val handles: (String) -> Boolean = { text ->
        UnitConverter.parse(text) != null || extractExpression(text) != null
    }

    override suspend fun execute(request: TutorRequest): TaskController.ToolResult {
        val text = request.question
        UnitConverter.parse(text)?.let { conv ->
            val answer = when (val r = UnitConverter.convert(conv)) {
                is UnitConverter.Result.Ok -> r.text
                is UnitConverter.Result.Error -> r.message
            }
            return TaskController.ToolResult.Handled(answer, ResponseMode.DETERMINISTIC)
        }
        val expression = extractExpression(text)
            ?: return TaskController.ToolResult.Unhandled("Not an arithmetic expression.")
        val answer = when (val r = ExpressionEvaluator.evaluate(expression)) {
            is EvalResult.Value -> "$expression = ${ExpressionEvaluator.format(r.value, r.exact)}"
            is EvalResult.Error -> r.message
        }
        return TaskController.ToolResult.Handled(answer, ResponseMode.DETERMINISTIC)
    }

    companion object {
        private val prefix = Regex("^(?:what is|what's|calculate|compute|evaluate|solve)\\s+")
        private val plainNumber = Regex("^[+-]?\\d+(?:\\.\\d+)?$")
        private val allowed = Regex("^[0-9\\s.+\\-*/^()%×÷−]+$")

        /** Returns the expression if the whole message is an arithmetic expression, else null. */
        internal fun extractExpression(raw: String): String? {
            var t = DigitNormalizer.toAscii(raw).trim().lowercase().replace(prefix, "").trimEnd('?', '=', '.', ' ')
            if (t.isEmpty() || t.length > ExpressionEvaluator.MAX_LENGTH) return null
            val stripped = t.replace("sqrt", "").replace("abs", "")
            if (!allowed.matches(stripped)) return null
            if (!stripped.any { it.isDigit() }) return null
            if (plainNumber.matches(t.replace(" ", ""))) return null
            if (stripped.none { it in "+-*/^%×÷−" } && t == stripped) return null
            return t
        }
    }
}
